Definition seccomp_bytes : gmap Z (bv 8) :=
  list_to_map (List.concat [
    seccomp_bytes_chunk0; seccomp_bytes_chunk1; seccomp_bytes_chunk2
  ]).

(* Total bytes = 2382 (from 886 instructions); keys are byte
   addresses, so [seccomp_bytes !! addr] yields that byte. *)

Global Typeclasses Opaque seccomp_bytes.

(* KEY RANGE.  [seccomp_bytes_lo <= a < seccomp_bytes_hi] for every key [a]: the decidable
   [map_Forall] check, closed by one [vm_compute], so the proof term is
   [eq_refl] and no list ever enters it.  Bounds are LITERALS (this file
   is below iris/ and cannot name [ram_lo]/[text_end]/[img_end]); the
   consumer bridges them arithmetically. *)
Definition seccomp_bytes_lo : Z := 0x0%Z.
Definition seccomp_bytes_hi : Z := 0x94e%Z.

Lemma seccomp_bytes_range_bool :
  bool_decide (map_Forall (fun (a : Z) (_ : bv 8) =>
                 (seccomp_bytes_lo <= a < seccomp_bytes_hi)%Z) seccomp_bytes) = true.
Proof. vm_compute. reflexivity. Qed.

Lemma seccomp_bytes_range (a : Z) (b : bv 8) :
  seccomp_bytes !! a = Some b -> (seccomp_bytes_lo <= a < seccomp_bytes_hi)%Z.
Proof.
  pose proof seccomp_bytes_range_bool as H.
  apply bool_decide_eq_true_1 in H. exact (H a b).
Qed.

